package popcount

import "math/bits"

// Popcount returns the number of set bits across all words of xs.
// A single hardware popcount intrinsic per word is the cheapest form in
// SSA terms: no chunking, no SWAR arithmetic, no horizontal fold.
func Popcount(xs []uint64) int {
	n := 0
	for _, x := range xs {
		n += bits.OnesCount64(x)
	}
	return n
}

